function validate([n, edges, k, t]) {
  if (!Number.isInteger(n) || n < 1 || n > 300) return 'n is an integer between 1 and 300.';
  if (!Array.isArray(edges) || edges.length > 300) return 'edges has at most 300 entries.';
  if (!Number.isInteger(k) || k < 0 || k > 300) return 'k is between 0 and 300.';
  if (!Number.isInteger(t) || t < 1 || t > 600) return 't is between 1 and 600.';
  const seen = new Set();
  const indegree = new Array(n).fill(0);
  const next = Array.from({ length: n }, () => []);
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 3) return 'Each edge is a triple [u, v, w].';
    const [u, v, w] = edge;
    if (!Number.isInteger(u) || !Number.isInteger(v) || u < 0 || u >= n || v < 0 || v >= n) return 'Nodes are labeled 0 to n - 1.';
    if (u === v) return 'An edge cannot join a node to itself.';
    if (!Number.isInteger(w) || w < 1 || w > 10) return 'Each weight is between 1 and 10.';
    if (seen.has(u * 300 + v)) return 'Each edge [u, v] may appear only once.';
    seen.add(u * 300 + v);
    next[u].push(v);
    indegree[v]++;
  }
  // Kahn's algorithm removes every node exactly when the graph has no cycle.
  const queue = [];
  for (let i = 0; i < n; i++) if (indegree[i] === 0) queue.push(i);
  for (let q = 0; q < queue.length; q++) {
    for (const v of next[queue[q]]) if (--indegree[v] === 0) queue.push(v);
  }
  if (queue.length !== n) return 'The graph must not contain a cycle.';
  return null;
}

