function maxWeight(n, edges, k, t) {
  let sums = Array.from({ length: n }, () => new Set([0]));
  for (let step = 1; step <= k; step++) {
    const next = Array.from({ length: n }, () => new Set());
    for (const [from, to, weight] of edges) {
      for (const sum of sums[from]) {
        if (sum + weight < t) {
          next[to].add(sum + weight);
        }
      }
    }
    if (next.every(set => set.size === 0)) return -1;
    sums = next;
  }

  let best = -1;
  for (const set of sums) {
    for (const sum of set) {
      best = Math.max(best, sum);
    }
  }
  return best;
}

