function maxWeight(n, edges, k, t) {
  // Walk every path of exactly k edges from every start node and keep the best total below t.
  const out = Array.from({ length: n }, () => []);
  for (const [u, v, w] of edges) out[u].push([v, w]);
  let best = -1;
  const walk = (node, used, total) => {
    if (used === k) {
      if (total < t) best = Math.max(best, total);
      return;
    }
    for (const [v, w] of out[node]) walk(v, used + 1, total + w);
  };
  for (let start = 0; start < n; start++) walk(start, 0, 0);
  return best;
}

