function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 200 + Math.floor(rand() * 101) : 1 + Math.floor(rand() * 7);
  // Shuffle the labels; edges only go forward in this order, so the graph never has a cycle.
  const order = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [order[i], order[j]] = [order[j], order[i]];
  }
  const heaviest = rand() < 0.3 ? 3 : 10;
  const seen = new Set();
  const edges = [];
  const add = (i, j) => {
    if (j >= n || seen.has(i * n + j)) return;
    seen.add(i * n + j);
    edges.push([order[i], order[j], 1 + Math.floor(rand() * heaviest)]);
  };
  if (large) {
    // A long backbone allows long paths; short forward jumps create many different totals. The jumps are drawn
    // from a shuffled list of at least 130 * 4 distinct pairs, so 300 edges are always reached without retrying.
    const backbone = 30 + Math.floor(rand() * 50);
    for (let i = 0; i < backbone; i++) add(i, i + 1);
    const jumps = [];
    for (let i = 0; i < backbone + 100; i++) {
      for (let d = 1; d <= 4; d++) jumps.push([i, i + d]);
    }
    for (let i = jumps.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [jumps[i], jumps[j]] = [jumps[j], jumps[i]];
    }
    for (const [i, j] of jumps) {
      if (edges.length === 300) break;
      add(i, j);
    }
  } else {
    const density = 0.3 + rand() * 0.7;
    for (let i = 0; i < n; i++) {
      for (let j = i + 1; j < n; j++) {
        if (rand() < density) add(i, j);
      }
    }
  }
  for (let i = edges.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [edges[i], edges[j]] = [edges[j], edges[i]];
  }
  // Small inputs favour short paths and a bound t in the upper part of the possible totals, so most have an answer.
  const k = large ? 5 + Math.floor(rand() * 35) : rand() < 0.1 ? 0 : 1 + Math.floor(rand() * rand() * Math.max(1, n - 1));
  const t = large ? 1 + Math.floor(rand() * 600) : 1 + Math.floor((0.4 + 0.6 * rand()) * (heaviest * Math.max(1, k) + 3));
  return [n, edges, k, t];
}
